<?php if (empty($adminPreview)): ?><div class="archive-modal hidden" id="archiveModal"><div class="archive-dialog"><h2>Archivar documento</h2><p><strong id="archiveTitle"></strong> dejará de aparecer entre los documentos vigentes. El archivo se conservará en el histórico.</p><form action="/yaconecta/public/admin/documentos/archive" method="POST"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="id" id="archiveId"><label>Motivo del archivo<textarea name="archive_reason" rows="3" required placeholder="Indica por qué se archiva esta versión"></textarea></label><div><button type="button" class="secondary-button" onclick="closeArchive()">Cancelar</button><button type="submit" class="archive-confirm">Confirmar archivo</button></div></form></div></div><?php endif; ?>
<script>
const adminPreview=<?= !empty($adminPreview) ? 'true' : 'false' ?>;
const formPanel=document.getElementById('docFormPanel');
function resetDocForm(){const form=document.getElementById('docForm');form.reset();document.getElementById('doc_id').value='';document.getElementById('formTitle').textContent='Subir nuevo documento';document.getElementById('filePrompt').textContent='Arrastra un archivo aquí';document.getElementById('doc_file').required=true;document.getElementById('saveDocButton').textContent='Guardar documento';form.action='/yaconecta/public/admin/documentos/store'}
function editDoc(doc){document.getElementById('formTitle').textContent='Editar documento';const form=document.getElementById('docForm');form.action='/yaconecta/public/admin/documentos/update';document.getElementById('doc_id').value=doc.id;document.getElementById('doc_code').value=doc.code;document.getElementById('doc_title').value=doc.title;document.getElementById('doc_type').value=doc.doc_type;document.getElementById('department_id').value=doc.department_id||'';document.getElementById('doc_version').value=doc.version;document.getElementById('doc_valid_from').value=doc.validity_date||'';document.getElementById('is_downloadable').checked=String(doc.is_downloadable)==='1';document.getElementById('doc_file').required=false;document.getElementById('filePrompt').textContent='Selecciona un archivo nuevo solo si deseas reemplazarlo';document.getElementById('saveDocButton').textContent='Guardar cambios';formPanel.scrollIntoView({behavior:'smooth',block:'start'})}
function showAdminTab(which){const active=which==='active';document.getElementById('activeTable').classList.toggle('hidden',!active);document.getElementById('archivedTable').classList.toggle('hidden',active);document.getElementById('tab-active').classList.toggle('active',active);document.getElementById('tab-archived').classList.toggle('active',!active)}
function openArchive(id,title){document.getElementById('archiveId').value=id;document.getElementById('archiveTitle').textContent=title;document.getElementById('archiveModal').classList.remove('hidden')}function closeArchive(){document.getElementById('archiveModal').classList.add('hidden')}
if(!adminPreview){document.querySelectorAll('[data-archive-id]').forEach(button=>button.addEventListener('click',()=>openArchive(button.dataset.archiveId,button.dataset.archiveTitle)));const fileInput=document.getElementById('doc_file'),dropZone=document.getElementById('dropZone');fileInput.addEventListener('change',()=>{if(fileInput.files.length)document.getElementById('filePrompt').textContent=fileInput.files[0].name});['dragenter','dragover'].forEach(ev=>dropZone.addEventListener(ev,e=>{e.preventDefault();dropZone.classList.add('dragging')}));['dragleave','drop'].forEach(ev=>dropZone.addEventListener(ev,e=>{e.preventDefault();dropZone.classList.remove('dragging')}));dropZone.addEventListener('drop',e=>{if(e.dataTransfer.files.length){fileInput.files=e.dataTransfer.files;fileInput.dispatchEvent(new Event('change'))}})}else{document.querySelectorAll('.admin-actions').forEach(cell=>cell.innerHTML='<span class="preview-lock">Solo lectura</span>')}
</script>
